//! #417: the MB-SMF's N2 MBS transfers against octets derived by hand from TS
//! 38.413 and X.691 (`super::golden`). Builders: the generated bytes are the
//! derived bytes for every input. Parsers: every derived transfer -- each
//! optional member, a NID, an unknown extension at each criticality, five
//! causes -- reads to its TMGI.
//!
//! These replace the old-vs-new oracle tests that compared the generated codec
//! with the hand-written `nextgcore-ngap::mbs_transfer` codec; neither that
//! crate nor `nextgcore-asn1c` is a dependency of mbsmfd any more.

use super::golden::*;
use super::*;
use proptest::prelude::*;

fn tmgi() -> impl Strategy<Value = NgapTmgi> {
    (any::<[u8; 3]>(), any::<[u8; 3]>())
}

fn tunnel() -> impl Strategy<Value = SharedMulticastTunnel> {
    (any::<[u8; 4]>(), any::<[u8; 4]>(), any::<u32>()).prop_map(
        |(multicast_address, source_address, teid)| SharedMulticastTunnel {
            multicast_address,
            source_address,
            teid,
        },
    )
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    #[test]
    fn setup_response_transfer_is_the_derived_octets(
        t in tmgi(),
        tunnel in tunnel(),
        qfi in 0u8..=MAX_QFI,
        five_qi in any::<u8>(),
    ) {
        let bytes = setup_response_transfer(t, tunnel, qfi, five_qi).unwrap();
        prop_assert_eq!(&bytes, &setup_response_octets(t, tunnel, qfi, five_qi));
        // And the strict generated decode reads them back.
        prop_assert_eq!(
            decode_setup_response(&bytes).unwrap(),
            SetupResponse { tmgi: t, tunnel: Some(tunnel), qfis: vec![qfi], activated: true }
        );
    }

    #[test]
    fn setup_unsuccessful_transfer_is_the_derived_octets(t in tmgi()) {
        prop_assert_eq!(setup_unsuccessful_transfer(t).unwrap(), setup_unsuccessful_octets(t));
    }

    #[test]
    fn a_minimal_setup_request_reads_to_its_tmgi(t in tmgi()) {
        prop_assert_eq!(parse_setup_request_tmgi(&setup_request_minimal_octets(t)).unwrap(), t);
    }

    #[test]
    fn a_setup_request_with_area_and_tunnel_reads_to_its_tmgi(
        t in tmgi(),
        area in any::<u16>(),
        address in any::<[u8; 4]>(),
        teid in any::<u32>(),
    ) {
        let bytes = setup_request_area_tunnel_octets(t, area, address, teid);
        prop_assert_eq!(parse_setup_request_tmgi(&bytes).unwrap(), t);
    }

    #[test]
    fn a_setup_request_with_a_nid_reads_to_its_tmgi(t in tmgi()) {
        prop_assert_eq!(parse_setup_request_tmgi(&setup_request_with_nid_octets(t)).unwrap(), t);
    }

    #[test]
    fn a_release_request_reads_to_its_tmgi(
        t in tmgi(),
        cause in proptest::sample::select(RELEASE_CAUSE_OCTETS.to_vec()),
        area_tunnel in proptest::option::of((any::<u16>(), any::<[u8; 4]>(), any::<u32>())),
    ) {
        let bytes = match area_tunnel {
            None => release_request_minimal_octets(t, cause),
            Some((area, address, teid)) => {
                release_request_area_tunnel_octets(t, area, address, teid, cause)
            }
        };
        prop_assert_eq!(parse_release_request_tmgi(&bytes).unwrap(), t);
    }
}

/// The derived NID vector is the generated codec's reading of it: the NID is
/// 44 bits and the area ID after it starts mid-octet, the one layout here that
/// is not octet-aligned throughout.
#[test]
fn the_nid_vector_decodes_to_its_members() {
    let t = ([0x02, 0xf8, 0x39], [0x00, 0x00, 0x01]);
    let d = nextgcore_ngap_gen::decode_contained::<g::MBS_DistributionSetupRequestTransfer>(
        &setup_request_with_nid_octets(t),
    )
    .unwrap();
    let nid = d.mbs_session_id.nid.expect("NID");
    assert_eq!(nid.0.len(), 44);
    assert_eq!(
        nid.0.iter().fold(0u64, |acc, b| (acc << 1) | u64::from(*b)),
        NID
    );
    assert_eq!(d.mbs_area_session_id.map(|a| a.0), Some(1));
    assert!(d.shared_ngu_unicast_tnl_information.is_some());
}

/// A Setup Request carrying one extension the V17.9 schema does not define
/// (ids 9 and 441): skipped at `ignore` and `notify`, refused at `reject`
/// (TS 38.413 §10.3.4.1).
#[test]
fn an_unknown_extension_is_skipped_unless_its_criticality_is_reject() {
    let t = ([0x02, 0xf8, 0x39], [0x00, 0x00, 0x01]);
    for id in [9u16, 441] {
        for (criticality, accepted) in [(0u8, false), (1, true), (2, true)] {
            let bytes = setup_request_with_extension_octets(t, id, criticality);
            assert_eq!(
                parse_setup_request_tmgi(&bytes).ok(),
                accepted.then_some(t),
                "id {id}, criticality {criticality}"
            );
        }
    }
}

/// The existing hand-derived goldens in main.rs's tests, read by the parsers.
#[test]
fn the_golden_requests_parse() {
    // GOLDEN_MBS_SETUP_REQ: TMGI 208/93 + 000001, area 1, GTP tunnel.
    let setup = [
        0x60, 0x02, 0xF8, 0x39, 0x00, 0x00, 0x01, 0x00, 0x00, 0x01, 0x01, 0xF0, 0x0A, 0x01, 0x02,
        0x03, 0x00, 0x00, 0x30, 0x39,
    ];
    let t = ([0x02, 0xF8, 0x39], [0x00, 0x00, 0x01]);
    assert_eq!(parse_setup_request_tmgi(&setup).unwrap(), t);
    // The same vector, from the derivation here.
    assert_eq!(
        setup_request_area_tunnel_octets(t, 1, [10, 1, 2, 3], 0x3039),
        setup
    );
    // GOLDEN_MBS_REL_REQ: TMGI 208/93 + C10202, nas/normal-release.
    let release = [0x00, 0x02, 0xF8, 0x39, 0xC1, 0x02, 0x02, 0x40];
    assert_eq!(
        parse_release_request_tmgi(&release).unwrap(),
        ([0x02, 0xF8, 0x39], [0xC1, 0x02, 0x02])
    );
}

#[test]
fn a_qfi_past_63_is_refused_as_before() {
    let tunnel = SharedMulticastTunnel {
        multicast_address: [232, 0, 0, 1],
        source_address: [10, 0, 0, 1],
        teid: 1,
    };
    assert!(
        setup_response_transfer((Default::default(), Default::default()), tunnel, 64, 9).is_err()
    );
}
